class Solution:
    def reconstructQueue(self, people: list[list[int]]) -> list[list[int]]:
        order = sorted(people, key=lambda p: (-p[0], p[1]))
        queue = []
        for person in order:
            queue = queue[:person[1]] + [person[:]] + queue[person[1]:]
        return queue

