class Solution:
    def reconstructQueue(self, people):
        n = len(people)
        bit = [0] * (n + 1)
        def add(i, delta):
            i += 1
            while i <= n:
                bit[i] += delta
                i += i & -i
        def kth(k):
            idx = 0
            bitmask = 1 << (n.bit_length() - 1)
            while bitmask:
                nxt = idx + bitmask
                if nxt <= n and bit[nxt] < k:
                    idx = nxt
                    k -= bit[nxt]
                bitmask >>= 1
            return idx
        for i in range(n):
            add(i, 1)
        ans = [None] * n
        for h, k in sorted(people, key=lambda p: (p[0], -p[1])):
            pos = kth(k + 1)
            ans[pos] = [h, k]
            add(pos, -1)
        return ans

